CREATE TABLE branch_price(tenant_id UUID NOT NULL,branch_id UUID NOT NULL,product_id UUID NOT NULL,price NUMERIC(19,2) NOT NULL CHECK(price>=0),version BIGINT NOT NULL,PRIMARY KEY(tenant_id,branch_id,product_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES product(tenant_id,id));
CREATE TABLE branch_price_history(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,branch_id UUID NOT NULL,product_id UUID NOT NULL,old_price NUMERIC(19,2) NOT NULL,new_price NUMERIC(19,2) NOT NULL,note VARCHAR(500) NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id,branch_id) REFERENCES branch(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES product(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES app_user(tenant_id,id));
CREATE INDEX ix_branch_price_history ON branch_price_history(tenant_id,branch_id,product_id,created_at);
